mod_adjust_modal_server <- function(id, n, rvals, proxy) {
    moduleServer(
        id,
        function(input, output, session) {
            ns <- session$ns
            tmp <- rvals$y                           # copy values for manipulation
            observeEvent(input$save_adjustment, {
                tmp[n, ]$carb <- input$adjust_value   # update value with that of the input slider
                updateReactable(outputId = "table", data = tmp) 
                rvals$y <<- tmp                      # globally copy updated values back to rvals$y
            }, ignoreInit = TRUE)
        }
    )
}



