# Define UI for application
ui <- fluidPage(
    tags$head(tags$script(
        ## JS to fire events on button clicks
        HTML('
             $(document).unbind("click").on("click", ".btn-group", function(e) {
                 console.log(e);
                 Shiny.setInputValue("button_clicked", e.target.id, {priority: "event"});
             });'
        )
    )),
    # Application title
    titlePanel("mtcars"),
    mainPanel(
        reactableOutput("table")
    )
)

# Define server logic required to draw a histogram
server <- function(input, output) {
    df <- mtcars[1:5, ] %>%
        mutate(
            example = glue::glue(
                '
                <div class = "btn-group btn-group-normal" role = "group">
                    <button id="example_{1:nrow(.)}" type="button" class="btn btn-default action-button">
                    Button
                    </button>
                </div>
                '
            )
        )
    
    # reactiveValues container
    # x is original data so that user can reset. 
    # y is what we'll generally use, and what we want to update.
    rvals <- reactiveValues(x = df, y = df)
    
    # main table, using rvals$y. 
    output$table <- renderReactable({
        reactable(
            data = rvals$y,
            columns = list(
                example = colDef(html = TRUE)
            )
        )
    })
    
    # observer watching all buttons and inferring which one is clicked
    observeEvent(input$button_clicked, {
        uid_split <- str_split(input$button_clicked, "_")[[1]]
        button <- uid_split[1]
        n <- uid_split[2]
        
        # based on clicked row (inferred from button_id), execute server and ui for 
        # for the module. Only one here, but real app has multiple module sets that launch
        # for different buttons.
        switch(
            button,
            "example" = {
                mod_adjust_modal_ui("example", n, rvals)
                mod_adjust_modal_server("example", n, rvals)
            }
        )
    })
    
}

# Run the application 
shinyApp(ui = ui, server = server)
